def recipe_play_pass(s, n):
    shiftText = ''
    for char in s:
        if char.isdigit():
            shiftText += str(10 - int(char))
        elif char.isalpha():
            # Circular shift: add n, wrap around 26
            base = ord('a')
            shifted = (ord(char.lower()) - base + n) % 26 + base
            shiftText += chr(shifted)
        else:
            shiftText += char

    caseText = ''
    for i in range(len(shiftText)):
        char = shiftText[i]
        if char.isalpha():
            if i % 2 == 0:
                caseText += char.upper()
            else:
                caseText += char.lower()
        else:
            caseText += char

    return caseText[::-1]
