```python
def fitness_dont_give_me_five(start, end):
    def count_without_five(n):
        if n < 0:
            return 0
        count = 0
        place = 1
        while place <= n:
            place *= 10
        place //= 10

        while place > 0:
            digit = (n // place) % 10
            count += place * digit
            if digit > 5:
                count -= place
            if digit == 5:
                break
            place //= 10

        count += 1
        return count

    if start > end:
        start, end = end, start

    return count_without_five(end) - count_without_five(start - 1)
