def mul_power(n, k):
    a = 1
    temp_n = n
    for p in range(2, int(temp_n ** 0.5) + 1):
        if temp_n % p == 0:
            m = 0
            while temp_n % p == 0:
                temp_n //= p
                m += 1
            remainder = m % k
            if remainder != 0:
                needed = k - remainder
                a *= p ** needed
    if temp_n > 1:
        remainder = 1 % k
        needed = k - remainder
        a *= temp_n ** needed
    return a

