        if n <= 1:
            return False
        for i in range(2, int(n ** 0.5) + 1):
            if n % i == 0:
                return False
        return True

    oversight_maxx = None
    for num in lst:
        if isPrime(num) and (oversight_maxx is None or num > oversight_maxx):
            oversight_maxx = num

    if oversight_maxx is None:
        return 0

    return sum(int(digit) for digit in str(oversight_maxx))
