from collections import deque

def draft_constrainedSubsetSum(nums, k):
    n = len(nums)
    dp = nums[:]
    monoq = deque()  # Stores tuples of (dp_value, index)

    for i in range(n):
        # Remove indices that are out of the window (i - index > k)
        while monoq and i - monoq[0][1] > k:
            monoq.popleft()

        # If window is valid, add dp[i-k] to current element
        if monoq:
            dp[i] = max(dp[i], dp[i] + monoq[0][0])

        # Maintain monotonicity (decreasing order of dp values)
        while monoq and monoq[-1][0] <= dp[i]:
            monoq.pop()

        monoq.append((dp[i], i))

    return max(dp)
```

