def eval_searchMatrix(matrix, target):
    if not matrix or target is None:
        return False
    rows, cols = len(matrix), len(matrix[0])
    if rows == 0 or cols == 0:
        return False
    low, high = 0, rows * cols - 1
    while low <= high:
        mid = (low + high) // 2
        num = matrix[mid // cols][mid % cols]
        if num == target:
            return True
        elif num < target:
            low = mid + 1
        else:
